const query=document.querySelector("#find-tool");query?.addEventListener("input",()=>{const r=query.value.trim().toLowerCase().split(/\s+/).filter(Boolean);let t=0;for(const n of document.querySelectorAll(".kit-group")){let e=0;for(const o of n.querySelectorAll(".kit-card")){const s=o.textContent.toLowerCase();o.hidden=!r.every(c=>s.includes(c)),o.hidden||e++}n.hidden=!e,t+=e}document.querySelector("#tool-search-status").textContent=r.length?t?t+" tools match your search.":"No tools match. Try a service, task or industry.":""});
